package com.onlinelibrary.controller;
import com.onlinelibrary.dao.impl.BookDAOImpl; import com.onlinelibrary.model.Book; import com.onlinelibrary.util.Validation; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet({"/librarian/books","/librarian/book-form"}) public class BookManagementServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{BookDAOImpl d=new BookDAOImpl();r.setAttribute("books",d.findAll());String id=r.getParameter("id");if(id!=null)r.setAttribute("book",d.findById(Long.parseLong(id)));WebSupport.view(r,s,r.getServletPath().endsWith("book-form")?"book-form.jsp":"books.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{String action=r.getParameter("action");BookDAOImpl d=new BookDAOImpl();if("delete".equals(action))d.delete(Long.parseLong(r.getParameter("id")));else{Book b=new Book();String id=r.getParameter("id");if(id!=null&&!id.isBlank())b.setId(Long.parseLong(id));b.setTitle(r.getParameter("title"));b.setAuthor(r.getParameter("author"));b.setIsbn(r.getParameter("isbn"));b.setGenre(r.getParameter("genre"));b.setPublisher(r.getParameter("publisher"));String year=r.getParameter("publicationYear");b.setPublicationYear(year==null||year.isBlank()?null:Integer.valueOf(year));b.setTotalQuantity(Integer.parseInt(r.getParameter("totalQuantity")));b.setAvailableQuantity(Integer.parseInt(r.getParameter("availableQuantity")));Validation.book(b);if(b.getId()==0){d.create(b);new com.onlinelibrary.dao.impl.NotificationDAOImpl().newArrival(b.getTitle());}else d.update(b);}s.sendRedirect(r.getContextPath()+"/librarian/books?message=Book+saved");}catch(Exception e){WebSupport.fail(r,s,e);}}}
